SELECT (percentile_cont(0.75) within GROUP (ORDER BY los) - percentile_cont(0.25) within GROUP (ORDER BY los)) AS interquartile_range FROM icustays WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND age(CURRENT_DATE, date_trunc('year', birthdate)) BETWEEN 84 AND 85 AND hadm_id IN (SELECT hadm_id FROM admissions WHERE admission_type_id = 1 AND (icd_code = '440.0' OR icd_code = '440.1'));